css:
.d1128-hammer,.d1128-deal,.d1128-boat{transform-box:fill-box}
.d1128-hammer{transform-origin:0% 0%;animation:d1128-a 3s ease-in-out infinite}
.d1128-deal{transform-origin:50% 100%;animation:d1128-b 3s ease-in-out infinite}
.d1128-boat{animation:d1128-c 3.6s ease-in-out infinite}
@keyframes d1128-a{0%,100%{transform:rotate(-25deg)}40%{transform:rotate(10deg)}55%{transform:rotate(-8deg)}}
@keyframes d1128-b{0%,35%,100%{transform:scaleY(1)}45%{transform:scaleY(.8)}}
@keyframes d1128-c{0%{transform:translate(0,0)}50%{transform:translate(70px,-3px)}70%,100%{transform:translate(70px,-3px) rotate(0)}}
@media (prefers-reduced-motion:reduce){.d1128-hammer{transform:rotate(10deg)}.d1128-boat{transform:translate(70px,-3px)}}
